<?php
require_once __DIR__ . '/_layout.php';requirePermission('cash.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$register=dbFetchOne("SELECT cr.*,a.name agency_name FROM cash_registers cr JOIN agencies a ON a.id=cr.agency_id WHERE cr.id=? AND cr.agency_id IN ($ph)",array_merge([$id],$ids));if(!$register){http_response_code(404);exit(t('validation.finance_not_found'));}
if(requestMethod()==='POST'){requireCsrfPost();try{$action=$_POST['action']??'';if($action==='manual')postManualCashMovement(['cash_register_id'=>$id,'movement_type'=>$_POST['movement_type']??'','amount'=>$_POST['amount']??'','reason'=>$_POST['reason']??'','idempotency_key'=>$_POST['idempotency_key']??'']);elseif($action==='close')closeCashRegister(['cash_register_id'=>$id,'actual_balance'=>$_POST['actual_balance']??'','reason'=>$_POST['reason']??'','notes'=>$_POST['notes']??'','idempotency_key'=>$_POST['idempotency_key']??'']);else throw new InvalidArgumentException(t('validation.invalid_action'));flash('success',t($action==='close'?'message.cash_closed':'message.cash_movement_created'));}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Cash register operation failed');flash('danger',t('message.cash_failed'));}safeRedirect('cash_register_detail.php?id='.$id);}
$movements=dbFetchAll('SELECT * FROM cash_movements WHERE cash_register_id=:id ORDER BY occurred_at,id',['id'=>$id]);backofficeHeader(t('page.cash_detail.title'),'cash.php');pageHeader('page.cash_detail.title','page.cash_detail.description',['breadcrumbs'=>[['label'=>'nav.finance','href'=>'finance.php'],['label'=>'nav.cash_register','href'=>'cash.php'],['label'=>$register['business_date']]]]);?>
<div class="grid"><section class="card"><div class="section-card-header"><h2><?=navigationIcon('admin')?><?=e($register['agency_name'])?></h2></div><dl class="detail-list"><dt><?=e(t('field.business_date'))?></dt><dd><?=formattedDate($register['business_date'])?></dd><dt><?=e(t('field.opening'))?></dt><dd><?=money($register['opening_balance'],$register['currency'])?></dd><dt><?=e(t('field.expected'))?></dt><dd><?=money($register['expected_balance']??0,$register['currency'])?></dd><dt><?=e(t('field.actual'))?></dt><dd><?=money($register['actual_balance']??0,$register['currency'])?></dd><dt><?=e(t('field.difference'))?></dt><dd><?=money($register['difference_amount']??0,$register['currency'])?></dd><dt><?=e(t('common.status'))?></dt><dd><?=statusBadge($register['status'])?></dd></dl></section><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.cash_movements'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.number'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.direction'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('field.date'))?></th></tr></thead><tbody><?php foreach($movements as$m):?><tr><td><?=isolatedValue($m['movement_number'],'reference-value')?></td><td><?=e(t('cash_movement.'.$m['movement_type']))?></td><td><?=e(t('direction.'.$m['direction']))?></td><td><?=money($m['amount'],$m['currency'])?></td><td><?=formattedDateTime($m['occurred_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php if($register['status']==='open'):?><div class="grid"><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.manual_cash_movement'))?></h2></div><form method="post"><?=csrfField()?><?=financeIdempotencyField('cash.manual')?><input type="hidden" name="action" value="manual"><label><?=e(t('field.type'))?><select name="movement_type"><option value="manual_in"><?=e(t('cash_movement.manual_in'))?></option><option value="manual_out"><?=e(t('cash_movement.manual_out'))?></option></select></label><label><?=e(t('field.amount'))?><input name="amount" inputmode="decimal" required></label><label><?=e(t('field.reason'))?><input name="reason" required maxlength="255"></label><button class="btn secondary"><?=e(t('action.record'))?></button></form></section><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.close_register'))?></h2></div><form method="post" data-confirm="<?=e(t('confirm.close_register'))?>"><?=csrfField()?><?=financeIdempotencyField('cash.close')?><input type="hidden" name="action" value="close"><label><?=e(t('field.counted_balance'))?><input name="actual_balance" inputmode="decimal" required></label><label><?=e(t('field.reason'))?><input name="reason" maxlength="255"></label><label><?=e(t('field.closing_notes'))?><input name="notes"></label><button class="btn primary"><?=e(t('action.close_register'))?></button></form></section></div><?php endif;?><?php backofficeFooter();
